I've tried to see if I could trigger the issue with a simple example, but to no avail. So it might indeed be a proper issue in our codebase.
```cpp
#include <cstdlib>
#include <iostream>
#include <time.h>
#include <vector>

int main() {
    std::vector<int> some_vec = { 0, 3, 18 };
    const int *some_int;
    bool is_set = false;
    
    srand (time(NULL));
    if (rand() % 2) {
        some_int = some_vec.data();
        is_set = true;
    }
    
    if (is_set) {
        some_int++;
        std::cout << *some_int << std::endl;
    }

    return 0;
}
```

This illustrates the problem:
```c++
#include <cstdlib>
#include <iostream>
#include <time.h>
#include <vector>

int main() {
    std::vector<int> some_vec = { 0, 3, 18 };
    const int *some_int;
    
    srand (time(NULL));
    if (rand() % 2) {
        some_int = some_vec.data();
    }
    
    if (some_int) {
        some_int++;
        std::cout << *some_int << std::endl;
    }

    return 0;
}
```

